{
  "table": {
    "name": "Patient",
    "purpose": "Rheumatology patient registry: one row per patient, with demographics, diagnosis dates, a serology flag, and diagnoses (SLE, Sjögren's, RA, Behçet's, PSS etc.). Referenced by Laboratory results."
  },
  "columns": {
    "col_001": {
      "role": "identifier",
      "name": "patient_id",
      "description": "Primary key; unique patient identifier. Referenced by Laboratory.col_001 (many laboratory rows per patient).",
      "status": "resolved"
    },
    "col_002": {
      "role": "category",
      "name": "sex",
      "description": "Sex: F (1023), M (202), blank (13). Strong female predominance consistent with autoimmune/rheumatic disease cohorts.",
      "status": "resolved"
    },
    "col_003": {
      "role": "date",
      "name": "date_of_birth",
      "description": "Patient date of birth (range 1912–2007, mostly 1930s–1960s).",
      "status": "resolved"
    },
    "col_004": {
      "role": "date",
      "name": "diagnosis_date",
      "description": "Date of diagnosis/registration, concentrated 1991–1998. Could be first-visit or diagnosis date; the exact event is not distinguishable from the data.",
      "status": "tentative"
    },
    "col_005": {
      "role": "date",
      "name": "onset_date",
      "description": "Disease onset or symptom-onset date (1972–1998, earlier and sparser than col_004, ~20% missing). Could alternatively be a follow-up/last-visit date, but earlier-than-diagnosis values favor onset.",
      "status": "tentative"
    },
    "col_006": {
      "role": "code",
      "name": "rheumatoid_factor",
      "description": "Serology flag, likely rheumatoid factor (or ANA) result: '-' negative (713), '+' positive (488), '+(' weak/ambiguous positive (3), blank (34). Which antibody is not determinable from the data.",
      "status": "tentative"
    },
    "col_007": {
      "role": "category",
      "name": "diagnosis",
      "description": "Diagnosis(es), free text with abbreviations of rheumatic/autoimmune diseases: SLE (systemic lupus erythematosus), SJS (Sjögren's syndrome), RA (rheumatoid arthritis), BEHCET, PSS (progressive systemic sclerosis / primary Sjögren's), DM (dermatomyositis), PN (polyarteritis nodosa) etc.; multiple diagnoses comma-separated.",
      "status": "resolved"
    }
  }
}
